from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
FIXTURE = TASK_DIR / "fixtures" / "public_case.json"
WORKFLOW = TASK_DIR / "workflow" / "cubed_sphere_case.py"
REPORT = TASK_DIR / "outputs" / "public_reproduction_report.json"


def reject_nonfinite_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON constant is not allowed: {value}")


def strict_json_loads(text: str) -> object:
    return json.loads(text, parse_constant=reject_nonfinite_constant)


def write_report(payload: dict[str, object], code: int) -> int:
    REPORT.parent.mkdir(parents=True, exist_ok=True)
    rendered = (
        json.dumps(
            payload,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
        + "\n"
    )
    REPORT.write_text(rendered, encoding="utf-8")
    print(rendered, end="")
    return code


def load_fixture() -> tuple[list[int], int]:
    fixture = strict_json_loads(FIXTURE.read_text(encoding="utf-8"))
    if not isinstance(fixture, dict) or set(fixture) != {
        "description",
        "edge_probes",
        "n",
        "process_hash_seeds",
    }:
        raise ValueError("public case has an unexpected schema")
    n = int(fixture["n"])
    seeds = [int(seed) for seed in fixture["process_hash_seeds"]]
    probes = fixture["edge_probes"]
    if not (3 <= n <= 32 and seeds and isinstance(probes, list) and probes):
        raise ValueError("public case is incomplete")
    return seeds, n


def run_seed(seed: int) -> dict[str, object]:
    completed = subprocess.run(
        [sys.executable, str(WORKFLOW), str(FIXTURE)],
        cwd=TASK_DIR,
        env={**os.environ, "PYTHONHASHSEED": str(seed)},
        check=False,
        capture_output=True,
        text=True,
        timeout=120,
    )
    if completed.returncode != 0:
        detail = completed.stderr.strip() or completed.stdout.strip()
        raise RuntimeError(
            f"connected-grid subprocess failed for hash seed {seed}: {detail}"
        )
    payload = strict_json_loads(completed.stdout)
    if not isinstance(payload, dict):
        raise ValueError("connected-grid subprocess did not return an object")
    return {"process_hash_seed": seed, **payload}


def main() -> int:
    try:
        seeds, n = load_fixture()
        observations = [run_seed(seed) for seed in seeds]
        connected_grid_contract_holds = bool(
            observations
            and all(
                item.get("connected_grid_contract_holds") is True
                for item in observations
            )
        )
        return write_report(
            {
                "schema_version": "2.0",
                "status": (
                    "post_fix_success"
                    if connected_grid_contract_holds
                    else "pre_fix_expected_failure"
                ),
                "scientific_check": "declared_cubed_sphere_neighbors",
                "grid_size": n,
                "observations": observations,
            },
            0 if connected_grid_contract_holds else 1,
        )
    except Exception as exc:  # noqa: BLE001 - keep runner errors distinct.
        return write_report(
            {
                "schema_version": "2.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )


if __name__ == "__main__":
    raise SystemExit(main())

